package com.bank.metrics.service;

import com.bank.metrics.repository.AccountRepository;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class TransferService {
    private static final Logger log = LoggerFactory.getLogger(TransferService.class);
    private final AccountRepository repo;
    private final Timer transferTimer;   // records latency distribution (p50/p95/p99)

    public TransferService(AccountRepository repo, MeterRegistry registry) {
        this.repo = repo;
        this.transferTimer = Timer.builder("bank.transfer.latency")
                .publishPercentiles(0.5, 0.95, 0.99)   // expose percentiles, not just mean
                .register(registry);
    }

    @Transactional
    public void transfer(String fromId, String toId, BigDecimal amount) {
        // Timer.record measures wall time of the DB work → feeds Prometheus/Grafana
        transferTimer.record(() -> {
            var from = repo.findById(fromId).orElseThrow();
            var to   = repo.findById(toId).orElseThrow();
            from.setBalance(from.getBalance().subtract(amount));
            to.setBalance(to.getBalance().add(amount));
            repo.save(from);
            repo.save(to);
        });
        log.info("Transfer {}→{} amount {} recorded in bank.transfer.latency timer",
                 fromId, toId, amount);
    }
}
